#version 300 es

#define HLSLCC_ENABLE_UNIFORM_BUFFERS 0
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
#define UNITY_UNIFORM
#else
#define UNITY_UNIFORM uniform
#endif
#define UNITY_SUPPORTS_UNIFORM_LOCATION 0
#if UNITY_SUPPORTS_UNIFORM_LOCATION
#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
uniform 	vec4 hlslcc_mtx4x4unity_ObjectToWorld[4];
uniform 	vec4 hlslcc_mtx4x4unity_MatrixVP[4];
uniform 	vec4 _MainTex_ST;
uniform 	mediump vec4 _Color;
uniform 	mediump vec4 _RendererColor;
uniform 	vec4 _Flip;
in highp vec4 in_POSITION0;
in highp vec4 in_COLOR0;
in highp vec2 in_TEXCOORD0;
out mediump vec4 vs_COLOR0;
out highp vec2 vs_TEXCOORD0;
vec4 u_xlat0;
vec4 u_xlat1;
void main()
{
    u_xlat0.xy = in_POSITION0.xy * _Flip.xy;
    u_xlat1 = u_xlat0.yyyy * hlslcc_mtx4x4unity_ObjectToWorld[1];
    u_xlat0 = hlslcc_mtx4x4unity_ObjectToWorld[0] * u_xlat0.xxxx + u_xlat1;
    u_xlat0 = hlslcc_mtx4x4unity_ObjectToWorld[2] * in_POSITION0.zzzz + u_xlat0;
    u_xlat0 = u_xlat0 + hlslcc_mtx4x4unity_ObjectToWorld[3];
    u_xlat1 = u_xlat0.yyyy * hlslcc_mtx4x4unity_MatrixVP[1];
    u_xlat1 = hlslcc_mtx4x4unity_MatrixVP[0] * u_xlat0.xxxx + u_xlat1;
    u_xlat1 = hlslcc_mtx4x4unity_MatrixVP[2] * u_xlat0.zzzz + u_xlat1;
    gl_Position = hlslcc_mtx4x4unity_MatrixVP[3] * u_xlat0.wwww + u_xlat1;
    u_xlat0 = in_COLOR0 * _Color;
    u_xlat0 = u_xlat0 * _RendererColor;
    vs_COLOR0 = u_xlat0;
    vs_TEXCOORD0.xy = in_TEXCOORD0.xy * _MainTex_ST.xy + _MainTex_ST.zw;
    return;
}


#version 300 es

precision highp float;
precision highp int;
#define HLSLCC_ENABLE_UNIFORM_BUFFERS 0
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
#define UNITY_UNIFORM
#else
#define UNITY_UNIFORM uniform
#endif
#define UNITY_SUPPORTS_UNIFORM_LOCATION 0
#if UNITY_SUPPORTS_UNIFORM_LOCATION
#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
uniform 	vec4 _MainTex_TexelSize;
uniform 	mediump vec4 _OutlineColor;
uniform 	float _OutlineSize;
UNITY_LOCATION(0) uniform mediump sampler2D _MainTex;
in mediump vec4 vs_COLOR0;
in highp vec2 vs_TEXCOORD0;
layout(location = 0) out mediump vec4 SV_Target0;
vec4 u_xlat0;
mediump vec4 u_xlat16_0;
vec4 u_xlat1;
mediump float u_xlat16_1;
vec2 u_xlat2;
mediump float u_xlat16_3;
mediump float u_xlat16_4;
mediump float u_xlat16_5;
mediump vec3 u_xlat16_7;
vec2 u_xlat8;
mediump float u_xlat16_8;
mediump float u_xlat16_12;
void main()
{
    u_xlat0.z = 0.0;
    u_xlat1.x = max(_OutlineSize, 0.0);
    u_xlat0.xy = u_xlat1.xx * _MainTex_TexelSize.xy;
    u_xlat0.w = (-u_xlat0.x);
    u_xlat1.xy = u_xlat0.wz + vs_TEXCOORD0.xy;
    u_xlat16_12 = texture(_MainTex, u_xlat1.xy).w;
    u_xlat1 = u_xlat0.xzzy + vs_TEXCOORD0.xyxy;
    u_xlat2.xy = u_xlat0.zy * vec2(1.0, -1.0) + vs_TEXCOORD0.xy;
    u_xlat16_8 = texture(_MainTex, u_xlat2.xy).w;
    u_xlat16_1 = texture(_MainTex, u_xlat1.xy).w;
    u_xlat16_5 = texture(_MainTex, u_xlat1.zw).w;
    u_xlat16_3 = max(u_xlat16_1, 0.0);
    u_xlat16_3 = max(u_xlat16_12, u_xlat16_3);
    u_xlat16_3 = max(u_xlat16_5, u_xlat16_3);
    u_xlat16_3 = max(u_xlat16_8, u_xlat16_3);
    u_xlat8.xy = u_xlat0.xy * vec2(0.707106769, 0.707106769) + vs_TEXCOORD0.xy;
    u_xlat16_8 = texture(_MainTex, u_xlat8.xy).w;
    u_xlat16_3 = max(u_xlat16_8, u_xlat16_3);
    u_xlat1.xy = u_xlat0.xy * vec2(0.707106769, 0.707106769);
    u_xlat0.xy = (-u_xlat0.xy) * vec2(0.707106769, 0.707106769) + vs_TEXCOORD0.xy;
    u_xlat16_0.x = texture(_MainTex, u_xlat0.xy).w;
    u_xlat1.zw = (-u_xlat1.xy);
    u_xlat1 = u_xlat1.zyxw + vs_TEXCOORD0.xyxy;
    u_xlat16_4 = texture(_MainTex, u_xlat1.xy).w;
    u_xlat16_8 = texture(_MainTex, u_xlat1.zw).w;
    u_xlat16_3 = max(u_xlat16_4, u_xlat16_3);
    u_xlat16_3 = max(u_xlat16_8, u_xlat16_3);
    u_xlat16_3 = max(u_xlat16_0.x, u_xlat16_3);
    u_xlat16_0 = texture(_MainTex, vs_TEXCOORD0.xy);
    u_xlat16_3 = (-u_xlat16_0.w) + u_xlat16_3;
    u_xlat16_3 = clamp(u_xlat16_3, 0.0, 1.0);
    u_xlat16_7.x = vs_COLOR0.w * _OutlineColor.w;
    u_xlat16_3 = u_xlat16_7.x * u_xlat16_3;
    u_xlat16_7.xyz = vec3(u_xlat16_3) * _OutlineColor.xyz;
    SV_Target0.w = u_xlat16_0.w * vs_COLOR0.w + u_xlat16_3;
    SV_Target0.w = clamp(SV_Target0.w, 0.0, 1.0);
    u_xlat16_0 = u_xlat16_0 * vs_COLOR0;
    SV_Target0.xyz = u_xlat16_0.xyz * u_xlat16_0.www + u_xlat16_7.xyz;
    return;
}

